# ================================================
# BrainStack Python: Student Management System
# Execution: python main.py
# ================================================

students = {}

def add_student():
    roll = input("Enter Roll Number: ")
    if roll in students:
        print("❌ Student already exists!")
        return
    name = input("Enter Name: ")
    age = input("Enter Age: ")
    course = input("Enter Course: ")
    students[roll] = {"name": name, "age": age, "course": course}
    print("✅ Student profile recorded successfully!")

def display_students():
    if not students:
        print("📭 Database directory is empty.")
        return
    print("\n--- Registered Student Directory ---")
    for roll, info in students.items():
        print(f"Roll: {roll} | Name: {info['name']} | Age: {info['age']} | Course: {info['course']}")

while True:
    print("\n=== BrainStack Student Management ===")
    print("1. Add New Student\n2. View Student Records\n3. Exit")
    choice = input("Select option (1-3): ")
    if choice == '1':
        add_student()
    elif choice == '2':
        display_students()
    elif choice == '3':
        print("👋 Database system offline.")
        break
    else:
        print("❌ Invalid entry. Try again!")

