import java.util.Scanner;

class BankAccount {
    private String holderName;
    private double balance;

    public BankAccount(String holderName, double initialBalance) {
        this.holderName = holderName;
        this.balance = initialBalance;
    }

    public double getBalance() {
        return balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("💸 Successfully deposited: $" + amount);
        } else {
            System.out.println("❌ Invalid deposit amount!");
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.println("🏧 Successfully withdrew: $" + amount);
        } else {
            System.out.println("❌ Insufficient balance or invalid action!");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        BankAccount account = new BankAccount("BrainStack Student", 500.00);

        System.out.println("=== WELCOME TO BRAINSTACK BANK ===");
        while (true) {
            System.out.println("\n1. Check Balance\n2. Deposit\n3. Withdraw\n4. Exit");
            System.out.print("Choose option: ");
            int choice = scanner.nextInt();

            if (choice == 1) {
                System.out.println("💰 Current Balance: $" + account.getBalance());
            } else if (choice == 2) {
                System.out.print("Enter amount to deposit: ");
                double amt = scanner.nextDouble();
                account.deposit(amt);
            } else if (choice == 3) {
                System.out.print("Enter amount to withdraw: ");
                double amt = scanner.nextDouble();
                account.withdraw(amt);
            } else if (choice == 4) {
                System.out.println("👋 Thank you for scaling with BrainStack!");
                break;
            } else {
                System.out.println("❌ Invalid option selected.");
            }
        }
        scanner.close();
    }
}

