#include <iostream>
#include <vector>
#include <string>

using namespace std; 

int main() {
    vector<string> tasks;
    int choice;
    string inputTask;

    cout << "=== BRAINSTACK TASK COMPILER ===\n";
    while (true) {
        cout << "\n1. Add Task\n2. View Tasks\n3. Delete First Task\n4. Exit\n";
        cout << "Select action code: ";
        cin >> choice;
        cin.ignore(); // Clear stream buffer

        if (choice == 1) {
            cout << "Enter task name: ";
            getline(cin, inputTask);
            tasks.push_back(inputTask);
            cout << "✔️ Task added successfully!\n";
        } 
        else if (choice == 2) {
            if (tasks.empty()) {
                cout << "📭 No active tasks found.\n";
            } else {
                cout << "\n--- YOUR ASSIGNMENTS ---\n";
                for (size_t i = 0; i < tasks.size(); ++i) {
                    cout << i + 1 << ". " << tasks[i] << "\n";
                }
            }
        } 
        else if (choice == 3) {
            if (!tasks.empty()) {
                cout << "🔥 Removed task: " << tasks[0] << "\n";
                tasks.erase(tasks.begin());
            } else {
                cout << "❌ Nothing to delete.\n";
            }
        } 
        else if (choice == 4) {
            cout << "🧠 BrainStack session closed. Goodbye!\n";
            break;
        } 
        else {
            cout << "❌ Selection mismatch. Try again!\n";
        }
    }
    return 0;
}
